function button(text,fn){const b=node('button',text);b.type='button';b.addEventListener('click',fn);return b;}
function field(parent,obj,key,label,{area=false,type='text',required=false,cls='',lang=''}={}){const id='field-'+key;const l=node('label',label+(required?' *':''));l.htmlFor=id;const input=node(area?'textarea':'input');input.id=id;input.name=key;if(!area)input.type=type;input.value=obj[key];input.className=cls;input.required=required;input.maxLength=30000;if(lang)input.lang=lang;if(type==='number'){input.min=49;input.max=9999;}if(key==='month')input.pattern='20[0-9]{2}-(0[1-9]|1[0-2])';let recorded=false;input.addEventListener('focus',()=>recorded=false);input.addEventListener('input',()=>{if(!recorded){remember();recorded=true;}obj[key]=type==='number'?Number(input.value):input.value;if(['text','title','language'].includes(key)&&obj.id){obj.proofread=false;obj.translations=false;}if(['poet','authorBio'].includes(key)&&obj.id)obj.profile=false;if(key.startsWith('editorial'))draft.editorialChecked=false;if(['coverStory','coverReference'].includes(key))draft.coverChecked=false;if(obj.authorId?.startsWith('new-')&&['poet','authorBio'].includes(key))for(const entry of draft.poems)if(entry.authorId===obj.authorId)entry[key]=obj[key];changed();nav();if(key==='theme')renderCoverTheme();if(key==='title')$('page-name').textContent=input.value||'Untitled entry';});input.addEventListener('change',()=>{nav();});parent.append(l,input);return input;}
