function languagePicker(parent,p){const l=node('label','Language');l.htmlFor='entry-language';const select=node('select');select.id='entry-language';for(const [value,name]of [['or','ଓଡ଼ିଆ'],['hi','हिन्दी'],['en','English']]){const o=node('option',name);o.value=value;select.append(o);}select.value=p.language;select.addEventListener('change',()=>{remember();p.language=select.value;p.proofread=false;p.translations=false;changed();for(const e of $('paper').querySelectorAll('[lang]'))e.lang=p.language;});parent.append(l,select);}
