  if(preview){const title=node('h2',p.title),body=node('div',p.text,'verse');title.lang=body.lang=p.language;paper.append(title,node('p',p.poet,'byline'),body,node('p',p.credits,'hint'));}else{const f=form(paper);field(f,p,'title',p.kind==='article'?'Article title':'Poem title',{cls:'title',required:true,lang:p.language});authorPicker(f,p);languagePicker(f,p);const verse=field(f,p,'text',p.kind==='article'?'Article text · preserve paragraphs':'Original poem · preserve line and stanza breaks',{area:true,required:true,lang:p.language});verse.spellcheck=false;verse.setAttribute('autocorrect','off');field(pf,p,'credits','Translator / additional credits');}
  categoryPicker(pf,p);field(pf,p,'source','Submission reference or source',{required:true});field(pf,p,'notes','Production notes',{area:true});const list=node('fieldset');list.append(node('legend','Preparation checks'));for(const k of checks)check(list,p,k,labels[k]);pf.append(list);const actions=node('div',undefined,'actions');actions.append(button('Remove entry',()=>{if(!confirm('Remove this entry from this draft? Undo edit can restore it.'))return;remember();draft.poems=draft.poems.filter(x=>x.id!==p.id);selected='contents';changed();render();}));props.append(actions);
