let inboxGeneration=0;
const inboxStates={monthly:{},anthology:{}};
function resetSubmissionLists(){
 inboxGeneration++;$('submission-desks').hidden=true;
 for(const stream of Object.keys(inboxStates)){
  inboxStates[stream]={};$(stream+'-inbox').open=false;
  $(stream+'-inbox-list').replaceChildren();$(stream+'-inbox-status').textContent='';
  $(stream+'-inbox-more').hidden=true;$(stream+'-inbox-refresh').disabled=false;
 }
}
async function loadSubmissions(stream,reset=false){
 const state=inboxStates[stream];if(!actor||state.busy)return;
 const ticket=inboxGeneration;state.busy=true;
 const list=$(stream+'-inbox-list'),status=$(stream+'-inbox-status'),more=$(stream+'-inbox-more'),refresh=$(stream+'-inbox-refresh');
 refresh.disabled=more.disabled=true;status.textContent='Loading received submissions…';
 try{
  const rows=await cloud.submissions(stream,reset?undefined:state.cursor);
  if(ticket!==inboxGeneration)return;
  if(reset){list.replaceChildren();state.count=0;state.cursor=undefined;state.ids=new Set();}
  state.ids??=new Set();
  for(const row of rows){if(state.ids.has(row.id))continue;state.ids.add(row.id);
   const li=node('li'),name=node('strong',row.name),title=node('span',' — '+row.title);
   title.lang=['or','hi','en'].includes(row.language)?row.language:'en';li.append(name,title);list.append(li);
  }
  state.count=state.ids.size;state.cursor=rows.at(-1)?.id||state.cursor;state.loaded=true;
  more.hidden=rows.length<25;
  status.textContent=state.count?`${state.count} received submissions shown · one row per poem${more.hidden?'':' · more available'}.`:'No received submissions yet.';
 }catch(e){if(ticket===inboxGeneration)status.textContent=e.code==='permission-denied'?'This account does not have access to this submission desk.':'Could not load submissions. Check your connection and use Refresh to try again. Existing rows may be out of date.';}
 finally{if(ticket===inboxGeneration){state.busy=false;refresh.disabled=more.disabled=false;}}
}
function syncSubmissionMenu(){
 const active=isAnthology(draft)?'anthology':'monthly';
 for(const stream of Object.keys(inboxStates))$(stream+'-inbox').hidden=stream!==active;
 if($('submission-overview').open&&!inboxStates[active].loaded)loadSubmissions(active,true);
}
$('submission-overview').addEventListener('toggle',syncSubmissionMenu);
for(const stream of Object.keys(inboxStates)){
 $(stream+'-inbox-refresh').addEventListener('click',()=>loadSubmissions(stream,true));
 $(stream+'-inbox-more').addEventListener('click',()=>loadSubmissions(stream));
}

